XC.uruguay={cc:'UY',first:['Mateo','Valentina','Santiago','Martina','Joaquin','Camila','Bruno','Emma'],last:['Rodriguez','Gonzalez','Fernandez','Silva','Pereira','Martinez','Rodrigues','Suarez'],facts:['carries a thermos and a mate gourd everywhere, including the beach','can recite the great chivito sandwich recipe with deep national pride','talks about the 1950 football World Cup win as if it happened last Tuesday'],fig:{'Gardel2':['Uruguayans say Carlos Gardel was born in Tacuarembo, which is a friendly argument with Argentina','Both sides agree the voice was unforgettable'],'Zitarrosa':['Alfredo Zitarrosa was a beloved folk singer whose deep voice made guitar songs feel like old friends','Fans still sing his songs at gatherings'],'Candombe':['Candombe is a drum tradition from Montevideo played at the Llamadas parade each year','Drummers walk the streets with their drums warmed by a fire first']}};
XC.venezuela={cc:'VE',first:['Mateo','Valentina','Santiago','Andrea','Luis','Gabriela','Carlos','Daniela'],last:['Rodriguez','Gonzalez','Perez','Hernandez','Garcia','Martinez','Lopez','Ramirez'],facts:['has a passionate opinion about the right filling for an arepa','insists that a cachapa with cheese is the finest breakfast of champions','lives near Angel Falls, the tallest waterfall in the world, and mentions it often'],fig:{'Maria Lionza':['Maria Lionza is a beloved spirit of nature and healing in Venezuelan folk belief','Pilgrims visit her mountain in the state of Yaracuy with flowers and thanks'],'Cuarto':['Simon Diaz wrote Caballo Viejo, a song sung around the world and loved at every family party','He also hosted a TV show where he sang songs of the plains for children'],'Canaima':['Canaima is the national park of table mountains called tepuis, some of the oldest rocks on earth','Local Pemon people tell stories about the spirits living on top of them']}};
