XC.afghanistan={cc:'AF',first:['Ahmad','Zahra','Farid','Laila','Jawid','Masooma','Hamid','Shabnam','Najib','Parwin','Rahim','Soraya','Bashir','Mariam','Qais','Nazanin'],last:['Ahmadi','Karimi','Noori','Safi','Rahimi','Popal','Sadat','Wardak','Barakzai','Stanikzai','Yusufzai','Faizi','Hashimi','Mohmand','Rezaie','Azizi'],facts:['insists a guest must be offered tea at least three times before it counts as hospitality','will happily argue that Afghan pomegranates and grapes beat any others on Earth','can recite a line of Rumi or Hafez for nearly any life situation','takes kite flying very seriously and can spot a rival kite string from across the valley'],fig:{'Rumi':['Born in Balkh, he became one of the most loved poets in the world','His poems about love and tea-time friendship are still quoted on cards and mugs everywhere'],'Rabia Balkhi':['Poet of Balkh remembered as one of the first great women poets in Persian','Her verses are still recited and her name is on schools and prizes'],'Ahmad Zahir':['Singer called the Elvis of Afghanistan for his smooth voice and stylish suits','Mixed Afghan melodies with guitars and kept whole weddings dancing for decades'],'Nasruddin':['Folk wise-fool known for jokes where he outsmarts himself','Once searched for his lost key under the lamp because the light was better there']}};
XC.armenia={cc:'AM',first:['Armen','Anahit','Tigran','Narine','Hayk','Lilit','Vahe','Arpi','Gor','Mariam','Aram','Sona','Levon','Hasmik','Davit','Nairi'],last:['Petrosyan','Hovhannisyan','Grigoryan','Sargsyan','Avetisyan','Harutyunyan','Manukyan','Khachatryan','Mkrtchyan','Galstyan','Danielyan','Margaryan','Vardanyan','Asatryan','Baghdasaryan','Melkonyan'],facts:['proudly says apricots taste best in Armenia and has the scientific name Prunus armeniaca as proof','will remind you the alphabet was invented just for the Armenian language and show it off','can pull a chessboard out of nowhere because chess is taught in schools','insists a toast must be long, heartfelt and followed by brandy and more food'],fig:{'Mesrop Mashtots':['Created the Armenian alphabet around 405 CE with 36 original letters','Armenians still celebrate a holiday in his honor with books and good cheer'],'Komitas':['Priest and composer who collected thousands of Armenian folk songs','Gave village melodies a home in concert halls around the world'],'Tigran Petrosian':['Chess world champion in the 1960s nicknamed Iron Tigran for his defence','Was said to be nearly impossible to beat when sitting back and waiting'],'Charles Aznavour':['French singer of Armenian descent who wrote over a thousand songs','Kept performing into his nineties and still got standing ovations']}};
XC.azerbaijan={cc:'AZ',first:['Elchin','Aysel','Tural','Leyla','Rashad','Gunel','Farid','Nigar','Orkhan','Sevda','Kamran','Aynur','Vugar','Nurlan','Samira','Rufat'],last:['Mammadov','Aliyev','Hasanov','Huseynov','Guliyev','Ismayilov','Abdullayev','Hajiyev','Rzayev','Mustafayev','Valiyev','Jafarov','Karimov','Asgarov','Sadigov','Ibrahimov'],facts:['insists tea must come in a pear-shaped armudu glass with jam or sugar cubes','can argue for hours about whose plov is the best, and each version has a different rice','knows Baku is nicknamed the Land of Fire for a reason and loves to explain it','will tell you carpet weaving is a family art and every pattern has a story'],fig:{'Nizami Ganjavi':['Twelfth century poet from Ganja who wrote romantic epics like Layla and Majnun','His five long poems are known as the Khamsa and still inspire painters and singers'],'Uzeyir Hajibeyov':['Composer of the first opera in the Muslim world, Leyli and Majnun, in 1908','Also wrote the national anthem, so he is famous at every football match'],'Garry Kasparov':['Born in Baku, he became one of the greatest chess players of all time','Was world champion for fifteen years and still gives lectures with a smile'],'Dede Korkut':['Legendary storyteller of Turkic epics full of brave heroes and wise elders','Said to share advice in tales that end with a good feast and a blessing']}};
XC.bahrain={cc:'BH',first:['Hamad','Fatima','Khalid','Maryam','Yousif','Noora','Ali','Zainab','Isa','Amal','Salman','Hessa','Jasim','Latifa','Ebrahim','Ghada'],last:['Al Khalifa','Al Mannai','Al Zayani','Kanoo','Fakhro','Al Alawi','Almoayyed','Janahi','Buhazza','Al Hawaj','Al Aali','Jawad','Al Sayed','Albinali','Al Ghanem','Alsharif'],facts:['proudly explains that Bahrain was once famous for the best natural pearls in the Gulf','will remind you that machboos is better the next day, and so are most family gossip stories','can hold a conversation with a pearl diver story in under a minute','loves a strong cup of karak chai and a seat on the corniche at sunset'],fig:{'Dilmun':['Ancient civilization on the islands, remembered in old stories as a paradise land','Its burial mounds are so many that they cover whole stretches of desert'],'Pearl divers':['Brave divers who dived without modern gear and held their breath for about a minute','Their songs, called fijiri, are still performed and loved at celebrations'],'Pearl of Bahrain':['Bahraini natural pearls were prized by royal courts around the world','Some old pearls are still kept in museums and glow like tiny moons'],'Mohamed bin Faris':['Famous singer and oud player who shaped the traditional sawt style','His music is still played at family gatherings and cultural evenings']}};
XC.georgia={cc:'GE',first:['Giorgi','Nino','Levan','Tamar','Davit','Mariam','Zurab','Ketevan','Irakli','Salome','Nikoloz','Eka','Lasha','Natia','Tornike','Mzia'],last:['Beridze','Kapanadze','Gelashvili','Maisuradze','Lomidze','Tsiklauri','Gogoladze','Japaridze','Mamedov','Kvaratskhelia','Chkheidze','Abashidze','Dolidze','Meladze','Janelidze','Svanidze'],facts:['insists a supra feast is not complete until the tamada has given at least ten toasts','will explain that wine was made here in clay jars called qvevri for eight thousand years','can fold a khinkali dumpling with exactly nineteen pleats and judges you if you use a fork','sings polyphonic songs at the table and expects everyone to find a harmony part'],fig:{'Queen Tamar':['Medieval ruler of the golden age, remembered for wise leadership and the arts','Called King Tamar in her own time, as her title was even stronger than queen'],'Shota Rustaveli':['Twelfth century poet who wrote The Knight in the Panther Skin','Georgians treat the poem as national treasure and many know long parts by heart'],'Niko Pirosmani':['Self-taught painter famous for simple, warm scenes of feasts and animals','Is the subject of a famous song about a million red roses'],'Nona Gaprindashvili':['Chess grandmaster who became the first woman to earn the grandmaster title','Held the world title for many years and won a lot of fans']}};
XC.iran={cc:'IR',first:['Reza','Shirin','Dariush','Parisa','Kaveh','Mahsa','Arash','Roya','Babak','Leila','Siavash','Niloufar','Farhad','Azadeh','Omid','Sepideh'],last:['Hosseini','Karimi','Rahmani','Mousavi','Ahmadi','Jafari','Tehrani','Shirazi','Esfahani','Tabrizi','Nasiri','Farahani','Bahrami','Rostami','Kazemi','Zand'],facts:['insists that a taarof dance of politely refusing three times is part of good manners','will tell you Persian poetry is the right answer to nearly any problem','can sit at a Nowruz table with seven items starting with S and explain each one','argues that saffron rice with a crispy tahdig bottom is the best part of dinner'],fig:{'Hafez':['Fourteenth century poet from Shiraz whose verses many keep on a bookshelf','Families open his book at random for a bit of advice on New Year'],'Ferdowsi':['Wrote the Shahnameh, a huge epic poem of about fifty thousand couplets','Spent around thirty years on it and kept the Persian language alive'],'Omar Khayyam':['Poet, mathematician and astronomer who helped refine the calendar','His quatrains about wine and the moment became world famous'],'Maryam Mirzakhani':['First woman to win the Fields Medal, the top prize in mathematics','Liked to doodle on huge sheets of paper while working on problems']}};
XC.iraq={cc:'IQ',first:['Ali','Zainab','Hussein','Noor','Omar','Rand','Mustafa','Sara','Karrar','Dalia','Haider','Hiba','Yasir','Lina','Ahmed','Ranya'],last:['Al Jubouri','Al Tamimi','Al Hashimi','Al Obaidi','Al Saadi','Al Bayati','Al Shammari','Al Rubaie','Al Kubaisi','Al Zubaidi','Al Janabi','Al Dulaimi','Al Samarrai','Al Khafaji','Al Naimi','Al Basri'],facts:['insists that no meal is complete without hot sweet tea in a small istikan glass','will say Mesopotamia was the cradle of writing and then humbly ask if you need a pen','can make masgouf fish by an open fire on the riverbank in a matter of hours','keeps a family recipe for dolma that is never written down, only remembered'],fig:{'Gilgamesh':['Legendary king of Uruk and hero of one of the oldest stories ever written','Travelled far to find the secret of life, and came home wiser and with a good tale'],'Enheduanna':['Priestess of Ur and the first named author in history, about 2300 BCE','Wrote hymns on clay tablets that are still read today'],'Al-Khwarizmi':['Mathematician in Baghdad whose name gave us the word algorithm','His book on algebra gave the world the name for that subject too'],'Zaha Hadid':['Baghdad born architect who won the Pritzker Prize','Designed sweeping curved buildings that look as if they are flowing']}};
XC.israel={cc:'IL',first:['Noa','Yoav','Tamar','Eitan','Maya','Itai','Shira','Amit','Yael','Nir','Liora','Omer','Dana','Gal','Tal','Roni'],last:['Cohen','Levi','Mizrahi','Peretz','Biton','Dahan','Avraham','Friedman','Katz','Shapira','Azulay','Goldberg','Ben David','Malka','Segal','Amar'],facts:['insists that a Friday breakfast needs shakshuka, salad and a lot of bread to count','will tell you hummus is the ultimate comfort food and then argue about which place is best','can start a friendly debate about anything over a single cup of coffee','loves a Friday night dinner where the whole extended family talks all at once'],fig:{'Ephraim Kishon':['Satirist whose funny stories about everyday life were read across Europe','Made a nation laugh at its own queues, bureaucracy and family dinners'],'Golda Meir':['Fourth prime minister, known for kitchen table talks over tea','Was famous for making visitors coffee and getting down to business'],'Ilan Ramon':['First Israeli astronaut who flew on the space shuttle Columbia','Brought a small drawing from a child made on his trip as a symbol of hope'],'Yehuda Amichai':['Poet who wrote about daily life in simple, warm and witty language','His verses are painted on walls and printed in school books']}};
