XC.malaysia={cc:'MY',first:['Ahmad','Siti','Wei Jie','Mei Ling','Rajesh','Priya','Hafiz','Nurul','Kevin','Aisyah','Jason','Kavitha','Farid','Lee','Zul','Aminah','Suresh','Hui Min'],last:['bin Abdullah','binti Hassan','Tan','Lim','Lee','Wong','Raj','Pillai','Chong','Kumar','Ismail','Yusof','Ng','Ibrahim','Krishnan','Ahmad'],facts:['can order nasi lemak for breakfast, lunch and dinner without shame','will happily argue about which state makes the best laksa','speaks a delightful mix of Malay, English, Chinese and Tamil in one sentence','knows that a teh tarik is not made until it has been pulled in a long stream','will say lah at the end of nearly every sentence for friendly emphasis','celebrates Hari Raya, Chinese New Year and Deepavali with equal enthusiasm and a lot of cookies'],fig:{'Hang Tuah':['Legendary Malay warrior of Melaka famed for loyalty and skill with the keris','Is said to have declared Takkan Melayu hilang di dunia, never shall the Malays vanish from the earth'],'Puteri Gunung Ledang':['Legendary princess of Mount Ledang who set impossible wedding conditions for a sultan','Her list included a bridge of gold and silver, which is quite a demanding bridal registry'],'Mat Kilau':['Folk hero of Pahang who resisted colonial rule in the late nineteenth century','Is remembered as a fighter of great courage, with films about his life'],'Sang Kancil':['Clever mouse-deer hero of Malay folk tales who outsmarts crocodiles and tigers','Famous for tricking crocodiles into lining up so he could hop across the river'],'Tun Dr Mahathir':['Long serving prime minister who loves writing, doctoring and being active in later life','Was still giving speeches in his nineties, so he is a model of staying busy']}};
XC.singapore={cc:'SG',first:['Wei Ming','Mei Hui','Aisha','Rajesh','Jun Hao','Siti','Priya','Kai Xiang','Farhan','Li Ting','Daniel','Shu Ying','Kumar','Jia Wen','Ryan','Nur','Ethan','Xin Yi'],last:['Tan','Lim','Lee','Ng','Wong','Chua','Goh','Teo','Ong','Koh','Singh','Rahman','Pillai','Chan','Yeo','Abdullah'],facts:['will politely reserve a table by placing a packet of tissue on it','knows which hawker centre sells the best chicken rice and will defend it fiercely','says can or cannot as a complete and efficient sentence','takes an umbrella everywhere because the weather loves a surprise','will queue for an hour for a famous bowl of laksa and call it a fair price','can switch between English, Singlish and a dialect without missing a beat'],fig:{'Sang Nila Utama':['Legendary prince from Sumatra said to have named Singapore after seeing a lion-like animal','Legend says he saw a creature on the shore and called the island Lion City'],'Hang Li Po':['Legendary Chinese princess in the Malay Annals who married the sultan of Melaka','Brought a retinue of five hundred attendants, which is a grand guest list'],'Raffles':['Colonial official who set up a trading post in 1819 and is remembered by a famous hotel and a statue','The statue has stood by the river for generations, greeting every passer-by'],'Lee Kuan Yew':['First prime minister, known for blunt speeches and a love for tidy streets','Is said to have kept a daily exercise routine, because discipline was his hobby'],'Badang':['Legendary strongman of ancient Singapore folk tale who gained power by eating the vomit of a water spirit','The Singapore Stone is said to have been thrown by him, a mighty throw indeed']}};
XC.indonesia={cc:'ID',first:['Budi','Siti','Agus','Dewi','Rizky','Putri','Bambang','Ayu','Wayan','Ketut','Joko','Sri','Dimas','Ratna','Eko','Wulan','Hendra','Indah'],last:['Santoso','Wijaya','Kusuma','Pratama','Hidayat','Saputra','Susanto','Lestari','Nugroho','Setiawan','Hartono','Purnama','Rahman','Gunawan','Siregar','Nasution'],facts:['will happily eat nasi goreng for breakfast and call it a perfectly normal start','knows jam karet, rubber time, means the meeting starts when everyone feels ready','can recite which island has the best rendang, sate or soto and defend it','will say makan dulu, eat first, before any serious conversation','loves a long family gathering where the food keeps arriving','rides a motorbike with a whole family and a bag of groceries without a second thought'],fig:{'Gajah Mada':['Prime minister of Majapahit who vowed not to taste spices until he united the archipelago','His famous oath, the Palapa, is still remembered in school lessons'],'Kartini':['Javanese pioneer of girls education whose letters inspired generations','Her birthday is celebrated every year with children wearing traditional dress'],'Malin Kundang':['Folk tale from West Sumatra about a son who forgot his mother and was turned into stone','The stone is said to be visible on a beach, a reminder to call home'],'Si Kancil':['Clever mouse-deer of Indonesian folk tales who outsmarts the crocodile and the farmer','Always wins with wit instead of strength, a good example for any contest'],'Dewi Sri':['Rice goddess honored in Java and Bali for a good harvest','Farmers still leave small offerings in the paddy fields to say thank you']}};
XC.brunei={cc:'BN',first:['Hasanah','Haji Ali','Nurul','Awang','Dayang','Aiman','Siti','Zul','Khairul','Mariam','Hairul','Amirah','Faizal','Najwa','Danial','Syafiqah'],last:['bin Abdullah','binti Ahmad','bin Hassan','binti Ibrahim','bin Ismail','binti Yusof','bin Omar','binti Salleh','bin Osman','binti Mohamad','bin Hamid','binti Ali','bin Said','binti Rahman','bin Jaafar','binti Kassim'],facts:['proudly lives in a country with a famous water village, Kampong Ayer, where homes stand on stilts','will serve you a plate of ambuyat, a sticky sago dish eaten with a bamboo fork','knows the golden dome of the Omar Ali Saifuddien Mosque is a pride of the capital','loves a quiet evening with a cup of sweet tea and kuih','will gently insist you try the local cake called kelupis','treats a long family gathering at Hari Raya as the best day of the year'],fig:{'Sultan Bolkiah':['Fifth sultan of Brunei, remembered as a sailor sultan who brought the empire to its peak','Tales say he traveled widely by ship and was called the Singing Captain'],'Nakhoda Ragam':['Legendary figure in the Brunei chronicle, said to have been a fearless captain','His stories are told in family gatherings with a sense of pride'],'Putri Junjung Buih':['Legendary princess in Malay tales said to have been found floating in the foam on a river','Folk songs describe her as graceful and wise, a good ruler in the tale'],'Sultan Omar Ali Saifuddien III':['Sultan remembered for building the great mosque in the capital','The mosque has a golden dome and a marble boat in its lagoon, which is quite a view'],'Awang Semaun':['One of the legendary thirteen brothers who founded Brunei in the old chronicles','The brothers are remembered in the early tales of the nation']}};
XC.timorleste={cc:'TL',first:['Joao','Maria','Jose','Ana','Domingos','Filomena','Armando','Lourenco','Lucia','Zacarias','Teresa','Mateus','Rosa','Agostinho','Natalia','Eduardo'],last:['da Costa','Soares','Ximenes','Guterres','Belo','Pereira','Freitas','Amaral','Araujo','Magalhaes','Gusmao','Carvalho','Correia','Martins','Lopes','Barros'],facts:['will warmly greet you with a good morning and ask about your family','knows that Timorese coffee is among the best in the world and will serve you a strong cup','loves a long afternoon of chatting under a tree with a plate of grilled fish','can speak Tetum, Portuguese and a local language in one conversation','will happily tell you the crocodile is the symbol of the island, a respected guardian','treats tais, the hand woven cloth, as a family treasure passed on with pride'],fig:{'The Crocodile Island':['Legend says a boy helped a crocodile and it grew into the island of Timor','The island is said to look like a crocodile lying in the sea, and people still honor it'],'Dom Boaventura':['Liurai leader of Manufahi who led a resistance in the early twentieth century','Is remembered in songs and statues as a proud leader'],'Nicolau Lobato':['Hero of the independence story, remembered as a leader and a man of the mountains','Roads and schools bear his name in remembrance'],'Xanana Gusmao':['Poet, painter and leader of Timor-Leste who loves writing and art','Wrote poems as well as speeches, a person of many talents'],'Bishop Belo':['Nobel Peace Prize winner in 1996 remembered as a gentle peacemaker','He is warmly remembered by the people for his kindness']}};
XC.cyprus={cc:'CY',first:['Andreas','Maria','Giorgos','Eleni','Christos','Despina','Nikos','Androulla','Kyriakos','Sophia','Panayiotis','Marios','Elena','Stavros','Costas','Anna'],last:['Georgiou','Christodoulou','Constantinou','Ioannou','Papadopoulos','Charalambous','Andreou','Michael','Nicolaou','Demetriou','Kyriakou','Savva','Pavlou','Loizou','Antoniou','Hadjikyriacou'],facts:['will say come, sit, eat, and then bring out far more food than you could ever finish','insists a bite of halloumi, grilled or fresh, makes every meal better','knows the island is the birthplace of Aphrodite, so beach days are practically a duty','will happily tell you the story of the world oldest wine, Commandaria','can spend an entire afternoon over a small cup of Cypriot coffee','will offer you a spoon sweet with a glass of cold water as a welcome'],fig:{'Aphrodite':['Goddess of love said by legend to have risen from the sea foam near Paphos','Folk tales say the beach is still the best place for a romantic walk'],'Zeno of Citium':['Philosopher from Cyprus who founded Stoicism in Athens','Taught that calm is a strength, a good lesson for anyone stuck in traffic'],'Digenis Akritas':['Legendary Byzantine hero of Cypriot folk tales, said to be so strong he threw rocks across the island','The Pentadaktylos mountain is said to carry the mark of his hand'],'Saint Barnabas':['Cypriot apostle born in Salamis and remembered as a kind friend and encourager','His name means son of encouragement, a lovely title'],'Evagoras':['King of Salamis in ancient times, remembered for bringing the city to prosperity','Statues of him stand as a reminder of an early island leader']}};
